  "track.fp.p4.sec.ex.b.01.exkt": "enum class Triage { RED, YELLOW, GREEN }\ndata class Visit(val urgent: Boolean, val triage: Triage)\nsealed interface Slot { data object Closed : Slot; data class Open(val triage: Triage) : Slot }\ntypealias OnBooked = (Booking?, Throwable?) -> Unit",
