  "track.fp.p4.sec.ex.b.01.solkt": "sealed interface BookResult {\n    data class Booked(val booking: Booking) : BookResult\n    data class Failed(val error: Throwable) : BookResult\n}\ntypealias OnBooked = (BookResult) -> Unit",
